INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Конституционные права и гарантии','Проект федерального закона предполагает, что права человека возникают только после их подтверждения государственным органом. Какой принцип Конституции нарушен?','["Основные права возникают только после регистрации гражданства","Основные права и свободы принадлежат человеку от рождения","Права устанавливаются исключительно решениями органов исполнительной власти","Права возникают лишь после наступления пенсионного возраста"]'::jsonb,1,'Конституция Российской Федерации','статья 17','https://www.minjust.gov.ru/ru/documents/8011/','Статья 17 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Гражданин ссылается на своё конституционное право, игнорируя при этом права другого лица. Какое конституционное ограничение действует?','["Осуществление собственных прав не должно нарушать права и свободы других лиц","Любое личное право всегда имеет безусловный приоритет","Коллизия прав решается только решением регионального правительства","Права допускается реализовывать лишь с предварительного согласия муниципалитета"]'::jsonb,0,'Конституция Российской Федерации','статья 17','https://www.minjust.gov.ru/ru/documents/8011/','Статья 17 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Ведомство отказывает гражданину в реализации конституционного права, поскольку отдельная ведомственная инструкция ещё не принята. Какой принцип применим?','["Все конституционные права действуют лишь после ведомственного регламента","Действие конституционных прав начинается после постановления Правительства","Непосредственно действуют лишь права работников государственных органов","Права и свободы непосредственно действуют и определяют применение законов"]'::jsonb,3,'Конституция Российской Федерации','статья 18','https://www.minjust.gov.ru/ru/documents/8011/','Статья 18 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Нормативный акт региона предусматривает разные возможности судебной защиты в зависимости от должности заявителя. Какая гарантия затронута?','["Исключительно свобода предпринимательской деятельности","Право на местное самоуправление","Равенство всех перед законом и судом","Свобода массовой информации"]'::jsonb,2,'Конституция Российской Федерации','статья 19','https://www.minjust.gov.ru/ru/documents/8011/','Статья 19 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Орган власти отказывает кандидату по признаку пола при равной профессиональной пригодности. Какое правило Конституции имеет непосредственное значение?','["Равенство признаётся только для граждан, замещающих должности депутатов","Равные права и свободы мужчины и женщины и равные возможности для их реализации","Пол и должностное положение могут свободно определять объём конституционных прав","Только региональный закон вправе гарантировать равенство мужчин и женщин"]'::jsonb,1,'Конституция Российской Федерации','статья 19','https://www.minjust.gov.ru/ru/documents/8011/','Статья 19 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Государственный орган хочет унизить человеческое достоинство лица в качестве дисциплинарной меры. Какой конституционный запрет применим?','["Достоинство личности охраняется государством и не может быть умалено","Охрана достоинства действует лишь после вынесения приговора","Достоинство является вопросом исключительной региональной компетенции","Дисциплинарные меры всегда позволяют унижать достоинство"]'::jsonb,0,'Конституция Российской Федерации','статья 21','https://www.minjust.gov.ru/ru/documents/8011/','Статья 21 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','В научном учреждении планируют медицинский эксперимент над человеком без его добровольного согласия. Что устанавливает Конституция?','["Достаточно решения руководителя учреждения","Достаточно согласия одного из членов исследовательской группы","Допускаются любые опыты при финансировании из бюджета","Без добровольного согласия такие опыты недопустимы"]'::jsonb,3,'Конституция Российской Федерации','статья 21','https://www.minjust.gov.ru/ru/documents/8011/','Статья 21 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Гражданина задержали без судебного решения на 60 часов. Какой конституционный предел необходимо учитывать?','["До судебного решения допускается задержание до 72 часов","Предел всегда составляет семь суток без судебного решения","До судебного решения задержание не может продолжаться более 48 часов","Предельный срок определяется только приказом начальника отдела"]'::jsonb,2,'Конституция Российской Федерации','статья 22','https://www.minjust.gov.ru/ru/documents/8011/','Статья 22 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Руководитель ведомства утверждает, что арест и содержание под стражей можно назначать без суда своим приказом. Какое требование действует?','["Судебное решение требуется только после истечения одного года","Арест и содержание под стражей допускаются только по судебному решению","Приказ ведомства всегда заменяет судебное решение","Судебный порядок применяется только к должностным лицам"]'::jsonb,1,'Конституция Российской Федерации','статья 22','https://www.minjust.gov.ru/ru/documents/8011/','Статья 22 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Орган власти собирается ограничить тайну переписки по обычному административному распоряжению без судебного решения. Какой способ ограничения предусмотрен Конституцией?','["Только на основании судебного решения","Любым ведомственным распоряжением","По требованию руководителя государственного предприятия","По устному согласию местной администрации"]'::jsonb,0,'Конституция Российской Федерации','статья 23','https://www.minjust.gov.ru/ru/documents/8011/','Статья 23 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Ведомство отказывает заявителю в защите сведений о семейной жизни, считая их публичными по умолчанию. Какое право гарантировано?','["Публичность всей семейной информации должностных лиц без исключений","Исключительная охрана только коммерческой тайны","Право любого органа публиковать чужие личные сведения","Неприкосновенность частной жизни и личная и семейная тайна"]'::jsonb,3,'Конституция Российской Федерации','статья 23','https://www.minjust.gov.ru/ru/documents/8011/','Статья 23 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Муниципальный орган размещает персональные сведения жителя о его частной жизни без согласия и без специального законного основания. Какой запрет действует?','["Запрет касается только федеральных органов, но не муниципалитетов","Любое опубликование сведений о частной жизни разрешено","Сбор, хранение, использование и распространение такой информации без согласия не допускаются","Ограничения касаются только документов с грифом секретности"]'::jsonb,2,'Конституция Российской Федерации','статья 24','https://www.minjust.gov.ru/ru/documents/8011/','Статья 24 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Орган государственной власти отказывается показывать гражданину материалы, непосредственно затрагивающие его права, не называя законного исключения. Какое обязательство закреплено Конституцией?','["Предоставлять такие материалы лишь депутатам Государственной Думы","Обеспечить доступ к непосредственно затрагивающим права материалам, если закон не устанавливает исключение","Открывать материалы исключительно после трёх лет хранения","Направлять заявителя только в органы местного самоуправления"]'::jsonb,1,'Конституция Российской Федерации','статья 24','https://www.minjust.gov.ru/ru/documents/8011/','Статья 24 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Должностное лицо хочет войти в чужое жилище против воли проживающих без судебного решения и без установленного федеральным законом случая. Как оценить действие?','["Оно нарушает конституционную неприкосновенность жилища","Оно допускается при письменном приказе любого руководителя","Оно допустимо, если сотрудник состоит на государственной службе","Оно допустимо после согласования с местной избирательной комиссией"]'::jsonb,0,'Конституция Российской Федерации','статья 25','https://www.minjust.gov.ru/ru/documents/8011/','Статья 25 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Ведомство требует от заявителей обязательно указывать национальную принадлежность в анкете независимо от целей обработки. Какой принцип действует?','["Национальность обязательно определяется государственным органом","Отказ указать национальность автоматически ограничивает конституционные права","Национальную принадлежность вправе устанавливать любой работодатель","Никто не может быть принуждён к определению и указанию своей национальности"]'::jsonb,3,'Конституция Российской Федерации','статья 26','https://www.minjust.gov.ru/ru/documents/8011/','Статья 26 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Организация запрещает гражданину самостоятельно выбирать язык общения без правового основания. Какое положение Конституции затронуто?','["Право только на выбор языка делопроизводства в федеральном министерстве","Право на использование лишь языка, выбранного работодателем","Право на свободный выбор языка общения и пользование родным языком","Исключительно полномочие региональной избирательной комиссии"]'::jsonb,2,'Конституция Российской Федерации','статья 26','https://www.minjust.gov.ru/ru/documents/8011/','Статья 26 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Гражданин законно находится в РФ, но его произвольно лишают возможности менять место пребывания. Какое конституционное право затронуто?','["Исключительное право на назначение выборов","Свобода передвижения и выбора места пребывания и жительства","Право на законодательную инициативу","Право на принятие государственного бюджета"]'::jsonb,1,'Конституция Российской Федерации','статья 27','https://www.minjust.gov.ru/ru/documents/8011/','Статья 27 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Гражданину РФ без законного основания отказывают в возвращении из-за рубежа в Россию. Какое положение прямо гарантирует его интерес?','["Право гражданина РФ беспрепятственно возвращаться в Российскую Федерацию","Право каждого иностранного гражданина автоматически получить гражданство РФ","Право любого гражданина требовать дипломатическую должность","Право возвращаться только по разрешению регионального парламента"]'::jsonb,0,'Конституция Российской Федерации','статья 27','https://www.minjust.gov.ru/ru/documents/8011/','Статья 27 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Орган власти требует от гражданина исповедовать определённую религию как условие обращения за муниципальной услугой. Какое право затронуто?','["Право на участие только в определённых религиозных объединениях","Право органа власти устанавливать вероисповедание заявителя","Свобода совести только для зарегистрированных объединений","Свобода совести, включая право не исповедовать никакой религии"]'::jsonb,3,'Конституция Российской Федерации','статья 28','https://www.minjust.gov.ru/ru/documents/8011/','Статья 28 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Руководитель требует публично отказаться от личных убеждений как условие занятия нейтральной государственной должности. Какой запрет применим?','["Принуждение допускается в любом государственном органе","Свобода мысли охватывает только научные мнения","Нельзя принуждать человека к выражению мнений или отказу от них","Запрет действует только на время избирательной кампании"]'::jsonb,2,'Конституция Российской Федерации','статья 29','https://www.minjust.gov.ru/ru/documents/8011/','Статья 29 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Законопроект устанавливает предварительную обязательную цензуру всех СМИ, не предусматривая законных исключений. Какая норма Конституции имеет значение?','["Цензура допускается по решению любого федерального министерства","Цензура запрещена","Свобода массовой информации гарантирована лишь государственным СМИ","Конституция не содержит положения о цензуре"]'::jsonb,1,'Конституция Российской Федерации','статья 29','https://www.minjust.gov.ru/ru/documents/8011/','Статья 29 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Ведомственный приказ предлагает самостоятельно определить полный перечень сведений, составляющих государственную тайну. Какой уровень акта требует Конституция?','["Федеральный закон","Приказ территориального органа власти","Муниципальное постановление","Решение общественной организации"]'::jsonb,0,'Конституция Российской Федерации','статья 29','https://www.minjust.gov.ru/ru/documents/8011/','Статья 29 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Работника заставляют вступить в общественное объединение под угрозой увольнения, не ссылаясь на законную обязанность. Какое положение Конституции применимо?','["Принудительное членство допускается по решению профсоюза","Право на объединение касается только партий","Запрет принуждения действует лишь для физических лиц старше 30 лет","Никого нельзя принуждать вступать в объединение или оставаться в нём"]'::jsonb,3,'Конституция Российской Федерации','статья 30','https://www.minjust.gov.ru/ru/documents/8011/','Статья 30 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Граждане РФ планируют мирную демонстрацию без оружия. Какое конституционное право они намерены реализовать?','["Право на заключение международного договора","Исключительное право на федеральную законодательную инициативу","Право на мирные собрания, митинги, демонстрации, шествия и пикетирования","Право на самостоятельное введение чрезвычайного положения"]'::jsonb,2,'Конституция Российской Федерации','статья 31','https://www.minjust.gov.ru/ru/documents/8011/','Статья 31 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Гражданин считает, что участвовать в делах государства можно только посредством избранных представителей. Что предусматривает Конституция?','["Допускается только представительное участие","Допускается участие как непосредственно, так и через представителей","Допускается только участие через государственные корпорации","Непосредственное участие разрешено лишь государственным служащим"]'::jsonb,1,'Конституция Российской Федерации','статья 32','https://www.minjust.gov.ru/ru/documents/8011/','Статья 32 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Гражданин отбывает наказание в виде лишения свободы по вступившему в силу приговору. Может ли он голосовать на выборах по Конституции?','["Нет, конституционное исключение распространяется на содержащихся в местах лишения свободы по приговору суда","Да, Конституция не допускает никаких ограничений","Да, при разрешении руководителя учреждения без изменения статуса","Нет, ограничение распространяется на всех лиц с любой судимостью"]'::jsonb,0,'Конституция Российской Федерации','статья 32','https://www.minjust.gov.ru/ru/documents/8011/','Статья 32 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','При назначении на государственную службу орган власти произвольно устанавливает разные права доступа для равно квалифицированных граждан. Какая гарантия затронута?','["Право исключительно юридических лиц участвовать в госслужбе","Обязанность граждан проходить военную службу вместо государственной","Полномочие региональной комиссии устанавливать должности","Равный доступ граждан Российской Федерации к государственной службе"]'::jsonb,3,'Конституция Российской Федерации','статья 32','https://www.minjust.gov.ru/ru/documents/8011/','Статья 32 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Группа граждан направляет коллективное обращение в орган местного самоуправления. Допускает ли это Конституция?','["Нет, гарантированы только индивидуальные обращения","Да, но только через депутата Госдумы","Да, гарантированы индивидуальные и коллективные обращения","Нет, обращения допускаются лишь в судебном процессе"]'::jsonb,2,'Конституция Российской Федерации','статья 33','https://www.minjust.gov.ru/ru/documents/8011/','Статья 33 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Компания стремится использовать экономические ресурсы для подавления конкурентов посредством недобросовестной конкуренции. Какое правило прямо содержит Конституция?','["Любая крупная компания автоматически признаётся незаконной","Экономическая деятельность, направленная на монополизацию и недобросовестную конкуренцию, недопустима","Конституция запрещает всякую частную экономическую деятельность","Конституция регулирует только конкуренцию между бюджетами субъектов"]'::jsonb,1,'Конституция Российской Федерации','статья 34','https://www.minjust.gov.ru/ru/documents/8011/','Статья 34 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Ведомство лишает собственника имущества своим окончательным решением без предусмотренного судебного решения. Какой конституционный стандарт нарушен?','["Лишение имущества допускается лишь по решению суда","Ведомственное решение всегда заменяет решение суда","Лишение имущества допускается голосованием муниципальной комиссии","Судебная процедура требуется только для организаций с госучастием"]'::jsonb,0,'Конституция Российской Федерации','статья 35','https://www.minjust.gov.ru/ru/documents/8011/','Статья 35 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Для государственных нужд планируется принудительное отчуждение имущества с компенсацией только через несколько лет и ниже его стоимости. Какой критерий нарушен?','["Достаточно любой компенсации после отчуждения","Предварительная компенсация предусмотрена только муниципальным правом","Конституция запрещает любую компенсацию за государственные нужды","Требуется предварительное и равноценное возмещение"]'::jsonb,3,'Конституция Российской Федерации','статья 35','https://www.minjust.gov.ru/ru/documents/8011/','Статья 35 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Региональный нормативный акт полностью исключает право граждан передавать имущество по наследству. Какое право нарушается?','["Наследование гарантировано только юридическим лицам","Право наследования зависит исключительно от усмотрения субъекта","Право наследования гарантировано Конституцией","Конституция гарантирует лишь наследование земли"]'::jsonb,2,'Конституция Российской Федерации','статья 35','https://www.minjust.gov.ru/ru/documents/8011/','Статья 35 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Собственник земли считает, что его правомочия безусловны даже при нанесении вреда природе и соседям. Какое ограничение действует?','["Ограничения применяются только к государственным участкам","Использование земли не должно наносить ущерб окружающей среде и нарушать права других лиц","Владение землёй полностью исключает земельное законодательство","Любое воздействие на природу допускается при уплате налога"]'::jsonb,1,'Конституция Российской Федерации','статья 36','https://www.minjust.gov.ru/ru/documents/8011/','Статья 36 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Работодатель требует обязательного труда под угрозой наказания без допустимого законного основания. Какой принцип нарушен?','["Принудительный труд запрещён","Принудительный труд допускается любым частным работодателем","Трудовые обязанности определяются только местным референдумом","Конституция запрещает лишь дополнительную оплачиваемую работу"]'::jsonb,0,'Конституция Российской Федерации','статья 37','https://www.minjust.gov.ru/ru/documents/8011/','Статья 37 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Региональная администрация предлагает произвольно выселять собственников без надлежащей процедуры. Какая гарантия затронута?','["Право на жилище распространяется только на жителей столицы","Жилищные гарантии предусмотрены только для госслужащих","Закон разрешает любое выселение по устному распоряжению","Никто не может быть произвольно лишён жилища"]'::jsonb,3,'Конституция Российской Федерации','статья 40','https://www.minjust.gov.ru/ru/documents/8011/','Статья 40 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Государственная больница требует оплату медицинской помощи, предоставляемой гражданам бесплатно за счёт бюджетных и страховых источников. Что закреплено Конституцией?','["Бесплатная помощь допускается исключительно в частных учреждениях","Конституция предусматривает оплату всех услуг исключительно пациентом","Бесплатная медицинская помощь гражданам в государственных и муниципальных учреждениях за счёт установленных источников","Бесплатная помощь гарантирована только федеральным государственным служащим"]'::jsonb,2,'Конституция Российской Федерации','статья 41','https://www.minjust.gov.ru/ru/documents/8011/','Статья 41 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Житель запрашивает достоверные сведения о состоянии окружающей среды в районе проживания. На какое право он ссылается?','["Право на доступ ко всем сведениям государственной тайны","Право на достоверную информацию о состоянии окружающей среды","Право самостоятельно отменять экологические законы","Право требовать должность в природоохранном ведомстве"]'::jsonb,1,'Конституция Российской Федерации','статья 42','https://www.minjust.gov.ru/ru/documents/8011/','Статья 42 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Родители утверждают, что основное общее образование ребёнка является исключительно добровольной услугой, не связанной с обязанностями. Что устанавливает Конституция?','["Основное общее образование обязательно, родители обеспечивают его получение детьми","Обязательное образование заканчивается после начальной школы","Общее образование обязательно только для совершеннолетних","Конституция устанавливает обязанность лишь дошкольного образования"]'::jsonb,0,'Конституция Российской Федерации','статья 43','https://www.minjust.gov.ru/ru/documents/8011/','Статья 43 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Абитуриент прошёл конкурс в государственный вуз. Какое конституционное положение относится к бесплатному высшему образованию?','["Безусловная бесплатность любого второго высшего образования без конкурса","Бесплатное обучение только по решению работодателя","Право на бесплатное обучение исключительно по муниципальному направлению","Бесплатное высшее образование на конкурсной основе в государственном или муниципальном образовательном учреждении и на предприятии"]'::jsonb,3,'Конституция Российской Федерации','статья 43','https://www.minjust.gov.ru/ru/documents/8011/','Статья 43 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Создатель произведения сталкивается с требованием отказаться от охраны интеллектуальных прав. Какая конституционная гарантия действует?','["Охрана интеллектуальной собственности допускается только после референдума","Интеллектуальные права принадлежат исключительно органам власти","Интеллектуальная собственность охраняется законом","Конституция защищает только недвижимое имущество"]'::jsonb,2,'Конституция Российской Федерации','статья 44','https://www.minjust.gov.ru/ru/documents/8011/','Статья 44 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Гражданин защищает нарушенное право способом, не запрещённым законом. Каково конституционное правило?','["Защита допускается только после получения статуса адвоката","Каждый вправе защищать свои права и свободы всеми не запрещёнными законом способами","Самостоятельная защита любых прав полностью запрещена","Допустим только способ, заранее согласованный с местным парламентом"]'::jsonb,1,'Конституция Российской Федерации','статья 45','https://www.minjust.gov.ru/ru/documents/8011/','Статья 45 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Гражданину отказали в возможности обжаловать действие государственного должностного лица в суд. Какая гарантия действует?','["Решения и действия или бездействие органов и должностных лиц могут быть обжалованы в суд","Судебное обжалование доступно только федеральным чиновникам","Суд рассматривает только споры между государственными органами","Обжалование возможно лишь после решения парламента"]'::jsonb,0,'Конституция Российской Федерации','статья 46','https://www.minjust.gov.ru/ru/documents/8011/','Статья 46 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Судебный орган хочет произвольно передать дело суду, которому оно не подсудно по закону. Какая гарантия нарушается?','["Право каждого заявителя самостоятельно назначить любого судью","Право регионального правительства выбирать суд по каждому делу","Право стороны требовать исключительно рассмотрения в федеральном министерстве","Право на рассмотрение дела тем судом и судьёй, к подсудности которых оно отнесено законом"]'::jsonb,3,'Конституция Российской Федерации','статья 47','https://www.minjust.gov.ru/ru/documents/8011/','Статья 47 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Следователь требует, чтобы обвиняемый доказывал свою невиновность. Какой принцип Конституции это опровергает?','["Обвиняемый всегда доказывает отсутствие вины","Обвиняемый освобождается от такой обязанности только при признании вины","Обвиняемый не обязан доказывать свою невиновность","Бремя доказывания определяется исключительно указом главы субъекта"]'::jsonb,2,'Конституция Российской Федерации','статья 49','https://www.minjust.gov.ru/ru/documents/8011/','Статья 49 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true),
('Конституционные права и гарантии','Свидетеля принуждают давать показания против супруга без учёта конституционной гарантии. Какая норма применяется?','["Отказ допускается только после получения статуса депутата","Никто не обязан свидетельствовать против себя самого, своего супруга и близких родственников по определённому законом кругу","Конституция освобождает лишь от показаний против коллег","Гарантия относится исключительно к имущественным отношениям"]'::jsonb,1,'Конституция Российской Федерации','статья 51','https://www.minjust.gov.ru/ru/documents/8011/','Статья 51 Конституции РФ устанавливает соответствующую гарантию или ограничение; важно учитывать различие между правом и процедурой его реализации.',true)
